import unittest


def strlen(string: str) -> int:
    return len(string)


class TestStrlen(unittest.TestCase):
    def test_basic_strings(self):
        self.assertEqual(strlen(""), 0)
        self.assertEqual(strlen("a"), 1)
        self.assertEqual(strlen("abc"), 3)

    def test_strings_with_spaces(self):
        self.assertEqual(strlen(" "), 1)
        self.assertEqual(strlen("   "), 3)
        self.assertEqual(strlen("hello world"), 11)

    def test_special_characters(self):
        self.assertEqual(strlen("!@#$%^&*()"), 10)
        self.assertEqual(strlen("\t\n"), 2)

    def test_unicode(self):
        self.assertEqual(strlen("héllo"), 5)
        self.assertEqual(strlen("你好"), 2)
        self.assertEqual(strlen("🙂"), 1)

    def test_long_string(self):
        self.assertEqual(strlen("x" * 1000), 1000)


def test_strlen():
    assert strlen("") == 0
    assert strlen("abc") == 3
    assert strlen("hello world") == 11
    assert strlen(" ") == 1
    assert strlen("a" * 50) == 50


if __name__ == "__main__":
    unittest.main()
